```go
if err, ok := p.(error); ok { ... } else { panic(p) }
```

But then the closure's recover would... actually, if I re-panic inside the recover, the deferred Close still runs, and then the panic propagates. That's reasonable. But the simplest thing is to handle both cases. Let me write it cleanly:

```go
func Use(opener ResourceOpener, input string) error {
	var r Resource
	var err error
	for {
		r, err = opener()
		if err == nil {
			break
		}
		if _, ok := err.(TransientError); !ok {
			return err
		}
	}

	defer r.Close()

	func() {
		defer func() {
			if p := recover(); p != nil {
				if fe, ok := p.(FrobError); ok {
					r.Defrob(fe.defrobTag)
					err = fe
				} else if e, ok := p.(error); ok {
					err = e
				} else {
					panic(p)
				}
			}
		}()
		r.Frob(input)
	}()

	return err
}
```

