package erratum

// Use opens a resource via opener, calls Frob(input) on it and ensures the
// resource is closed exactly once. It retries while the opener returns a
// TransientError, recovers from panics raised by Frob (calling Defrob with
// the FrobError's defrobTag when applicable) and returns any error that
// occurs.
func Use(opener ResourceOpener, input string) error {
	var r Resource
	var err error
	for {
		r, err = opener()
		if err == nil {
			break
		}
		if _, ok := err.(TransientError); !ok {
			return err
		}
	}

	defer r.Close()

	func() {
		defer func() {
			if p := recover(); p != nil {
				switch v := p.(type) {
				case FrobError:
					r.Defrob(v.defrobTag)
					err = v
				case error:
					err = v
				default:
					panic(p)
				}
			}
		}()
		r.Frob(input)
	}()

	return err
}
